// Decide se este disparo do cron caiu na janela de limpeza.
// A regra de negocio vem do texto cadastrado na FAQ.
const faq = $('Buscar horario na FAQ').first().json;
const variaveis = $('Variaveis limpeza follow-ups').first().json;
const timezone = String(variaveis.timezone ?? '').trim();
if (!timezone) throw new Error('TIMEZONE_LIMPEZA_FOLLOWUPS_NAO_CONFIGURADO');
const resposta = String(faq.resposta ?? '').trim();
const textoNormalizado = resposta
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();

const agoraPartes = new Intl.DateTimeFormat('pt-BR', {
  timeZone: timezone,
  weekday: 'long',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
}).formatToParts(new Date());

const parte = (tipo) => agoraPartes.find((item) => item.type === tipo)?.value ?? '';
const diaSemana = parte('weekday').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const horaAtualMinutos = Number(parte('hour')) * 60 + Number(parte('minute'));
const cronMinutos = Number(variaveis.intervalo_cron_minutos);
const atrasoLimpezaMinutos = Number(variaveis.atraso_limpeza_minutos);
if (![cronMinutos, atrasoLimpezaMinutos].every(Number.isFinite)) throw new Error('CONFIG_LIMPEZA_FOLLOWUPS_INVALIDA');

const ehDiaUtil = ['segunda-feira', 'terca-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira'].includes(diaSemana);
const ehSabado = diaSemana === 'sabado';
const ehDomingo = diaSemana === 'domingo';

const extrairFim = (regex) => {
  const match = textoNormalizado.match(regex);
  if (!match) return null;
  const hora = Number(match[3]);
  const minuto = Number(match[4] ?? 0);
  if (!Number.isFinite(hora) || !Number.isFinite(minuto)) return null;
  return hora * 60 + minuto;
};

let fimExpedienteMinutos = null;
if (ehDiaUtil) {
  fimExpedienteMinutos = extrairFim(/segunda\s+a\s+sexta\s+(\d{1,2})(?::(\d{2}))?\s*(?:as|a|-)\s*(\d{1,2})(?::(\d{2}))?/);
}
if (ehSabado) {
  fimExpedienteMinutos = extrairFim(/sabado\s+(\d{1,2})(?::(\d{2}))?\s*(?:as|a|-)\s*(\d{1,2})(?::(\d{2}))?/);
}

const inicioJanela = fimExpedienteMinutos === null ? null : fimExpedienteMinutos + atrasoLimpezaMinutos;
const fimJanela = inicioJanela === null ? null : inicioJanela + cronMinutos;
const dentroJanelaLimpeza = !ehDomingo
  && inicioJanela !== null
  && horaAtualMinutos >= inicioJanela
  && horaAtualMinutos < fimJanela;

return [{
  json: {
    faq_horario_id: faq.id ?? null,
    faq_horario_nome: faq.nome ?? '',
    faq_horario_resposta: resposta,
    dia_semana: diaSemana,
    hora_atual_minutos: horaAtualMinutos,
    fim_expediente_minutos: fimExpedienteMinutos,
    limpar_followups: dentroJanelaLimpeza,
    motivo: dentroJanelaLimpeza
      ? 'FIM_EXPEDIENTE_MAIS_5_MINUTOS'
      : 'FORA_DA_JANELA_DE_LIMPEZA'
  }
}];
